// "Source config": the source to collect. Called by the orchestrator, it gets one source object.
// On a test run it falls back to 3-1-1.
const raw = $input.first()?.json ?? {};
const given = raw.headers && raw.body ? raw.body : raw; // the test webhook wraps its input in body
const s = given.dataset ? given : {
  id: "311",
  portal: "https://opendata.vancouver.ca",
  dataset: "3-1-1-service-requests",
  label: "3-1-1 service requests",
  source_note: "City of Vancouver open data, 3-1-1 service requests",
  source_url: "https://opendata.vancouver.ca/explore/dataset/3-1-1-service-requests/",
  unit: "reports",
  date_field: "service_request_open_timestamp",
  category_field: "service_request_type",
  area_field: "local_area",
  date_only: false,
  max_age_hours: 48,
  filter: "",
};
const extra = s.filter ? ` and (${s.filter})` : "";
return [{ json: {
  ...s,
  // Date-only fields are stored at UTC midnight; grouping them in Vancouver time would shift every day back by one.
  timezone: s.date_only ? "UTC" : "America/Vancouver",
  base_url: `${s.portal}/api/explore/v2.1/catalog/datasets/${s.dataset}`,
  newest_select: `max(${s.date_field}) as newest`,
  // Some datasets hold future-dated records, so the newest record is the newest up to now.
  newest_where: `${s.date_field} <= now()${extra}`,
} }];

// "Set window": 9 weeks of 7 days ending on the Vancouver date of the newest record.
const s = $("Source config").first().json;
const newest = $input.first().json.results?.[0]?.newest;
if (!newest) return [{ json: { ok: false, source: s.label, reason: `${s.label}: the city API returned no newest record.` } }];
const day = s.date_only
  ? String(newest).slice(0, 10)
  : new Date(newest).toLocaleDateString("en-CA", { timeZone: "America/Vancouver" });
const addDays = (iso, n) => { const d = new Date(iso + "T12:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const ageHours = (Date.now() - new Date(newest).getTime()) / 36e5;
if (ageHours > s.max_age_hours) {
  return [{ json: { ok: false, source: s.label, reason: `${s.label}: the newest record is ${Math.round(ageHours)} hours old.` } }];
}
const start = addDays(day, -62);
const weekStart = addDays(day, -6);
const end = addDays(day, 1);
const extra = s.filter ? ` and (${s.filter})` : "";
const between = (a) => `${s.date_field} >= date'${a}' and ${s.date_field} < date'${end}'${extra}`;
return [{ json: {
  ok: true,
  newest_record: newest,
  week_ending: day,
  week_start: weekStart,
  daily: {
    select: `${s.category_field}, count(*) as n`,
    where: between(start),
    group_by: `${s.category_field}, date_format(${s.date_field}, 'yyyy-MM-dd') as day`,
  },
  area: {
    select: `${s.category_field}, ${s.area_field}, count(*) as n`,
    where: between(weekStart),
    group_by: `${s.category_field}, ${s.area_field}`,
  },
} }];

// "Build collected": days into weeks, plus this week's neighbourhood counts. See `collected` in _config/contracts.md.
const s = $("Source config").first().json;
const w = $("Set window").first().json;
const daily = $("Daily counts by category").all().map((i) => i.json);
const areas = $("This week by area").all().map((i) => i.json);
const addDays = (iso, n) => { const d = new Date(iso + "T12:00:00Z"); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const daysBetween = (a, b) => Math.round((new Date(b + "T12:00:00Z") - new Date(a + "T12:00:00Z")) / 864e5);
const weeks = Array.from({ length: 9 }, (_, k) => addDays(w.week_ending, -7 * (8 - k)));

const types = new Map();
const entry = (t) => {
  if (!types.has(t)) types.set(t, { type: t, weekly: weeks.map((we) => ({ week_ending: we, count: 0 })), by_area: [], unknown_area: 0 });
  return types.get(t);
};
for (const r of daily) {
  const t = r[s.category_field];
  if (!t || !r.day) continue;
  const k = 8 - Math.floor(daysBetween(r.day, w.week_ending) / 7);
  if (k >= 0 && k <= 8) entry(t).weekly[k].count += r.n;
}
for (const r of areas) {
  const t = r[s.category_field];
  if (!t) continue;
  const e = entry(t);
  if (r[s.area_field]) e.by_area.push({ area: r[s.area_field], count: r.n });
  else e.unknown_area += r.n;
}
for (const e of types.values()) e.by_area.sort((a, b) => b.count - a.count);
if (!types.size) return [{ json: { ok: false, source: s.label, reason: `${s.label}: no rows in the last 9 weeks.` } }];

return [{ json: {
  ok: true,
  source_id: s.id,
  dataset: s.label,
  source_note: s.source_note,
  source_url: s.source_url,
  unit: s.unit,
  newest_record: w.newest_record,
  week_start: w.week_start,
  week_ending: w.week_ending,
  weeks,
  types: [...types.values()],
} }];

// "Failed": every error in Collect ends here, so the orchestrator sends a short note instead of crashing.
const j = $input.first().json;
const reason = j.reason || `Collect failed: ${j.error?.message || j.message || "unknown error"}`;
return [{ json: { ok: false, step: "Collect", source: $("Source config").first()?.json?.label, reason } }];
